    {
      "mechanism_id": "msd_power_law",
      "statement": "The asymptotic MSD scales as a power law in time, <x^2(t)> ~ C(alpha) t^gamma(alpha), with exponent gamma(alpha) given piecewise. For alpha>3/2, gamma = 2 - 2/alpha.",
      "equations": [
        "gamma(alpha) = 2 - 2/alpha for alpha > 3/2",
        "<x^2(t)> ~ C(alpha) t^gamma(alpha)"
      ],
      "variable_names": [
        "gamma",
        "alpha",
        "t",
        "MSD",
        "C(alpha)"
      ],
